// Si se cambia el diseño en la deck, hay que volver a copiar las slides aquí.
window.PLANTILLA_ARK = [
{
"id": "cover",
"html": "<section id=\"cover\" data-transition=\"magic\" style=\"background:#0E0E0F;color:#FAFAF8;font-family:'Inter', Arial, sans-serif;padding:128px;display:flex;flex-direction:column;justify-content:space-between\">\n<div style=\"position:absolute;left:1100px;top:0px;width:820px;height:1080px;background:radial-gradient(circle at 70% 40%, #2A2A2D 0%, #0E0E0F 70%)\"></div>\n<img data-build-in=\"fade 1 auto\" src=\"propuesta/logo-blanco.png\" alt=\"\" style=\"position:absolute;left:1180px;top:300px;width:620px;height:401px;object-fit:contain;opacity:0.08\">\n<img id=\"ark-logo\" src=\"propuesta/logo-portada.png\" alt=\"Logo de ARK\" style=\"position:absolute;left:128px;top:128px;width:146px;height:120px;object-fit:contain\">\n<p data-build-in=\"fade 1 auto\" style=\"position:absolute;left:128px;top:367px;width:1240px;font-size:24px;letter-spacing:6px;text-transform:uppercase;color:#A1A1A6\">Propuesta de aplicación · {{fecha_propuesta}}</p>\n<h1 data-build-in=\"rise 1 auto\" style=\"position:absolute;left:128px;top:433px;width:1240px;font-family:'Manrope', Arial, sans-serif;font-size:120px;font-weight:300;line-height:1.05;letter-spacing:-3px\">{{nombre_app}}<br><span style=\"color:#A1A1A6\">para {{cliente_nombre}}</span></h1>\n<p data-build-in=\"rise 2 auto\" style=\"position:absolute;left:128px;top:717px;width:1000px;font-size:32px;line-height:1.4;color:#C9C9CC\">{{frase_valor}}</p>\n<div data-build-in=\"fade 3 auto\" style=\"position:absolute;left:128px;bottom:128px;width:1664px;display:flex;gap:64px\">\n<div style=\"display:flex;flex-direction:column;gap:4px\">\n<p style=\"font-size:24px;color:#77777C\">Preparado para</p>\n<p style=\"font-size:24px;font-weight:600\">{{cliente_contacto}} · {{cliente_cargo}}</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:4px\">\n<p style=\"font-size:24px;color:#77777C\">Presenta</p>\n<p style=\"font-size:24px;font-weight:600\">{{representante_nombre}} · ARK</p>\n</div>\n</div>\n<aside>Portada. Saluda, agradece el tiempo y confirma que la llamada dura unos 30 minutos. Variables: nombre_app, cliente_nombre, frase_valor (una línea con el beneficio principal), fecha_propuesta, cliente_contacto, cliente_cargo, representante_nombre.</aside>\n</section>"
},
{
"id": "agenda",
"html": "<section id=\"agenda\" data-transition=\"magic\" style=\"background:#FAFAF8;color:#0E0E0F;font-family:'Inter', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:64px\">\n<p data-build-in=\"fade 1 auto\" style=\"position:absolute;left:128px;top:128px;width:1664px;font-size:24px;letter-spacing:6px;text-transform:uppercase;color:#8A8A8F\">Agenda</p>\n<h2 data-build-in=\"rise 1 auto\" style=\"position:absolute;left:128px;top:178px;width:1664px;font-family:'Manrope', Arial, sans-serif;font-size:72px;font-weight:500;line-height:1.1;letter-spacing:-1.5px\">Lo que veremos hoy</h2>\n<div data-build-in=\"rise 2 auto\" style=\"position:absolute;left:128px;top:321px;width:1664px;display:grid;grid-template-columns:1fr 1fr 1fr;gap:0px;border-top:1px solid #E2E2DE\">\n<div style=\"display:flex;flex-direction:column;gap:8px;padding:32px 32px 32px 0px;border-bottom:1px solid #E2E2DE\"><p style=\"font-size:24px;color:#8A8A8F\">01</p><p style=\"font-size:32px;font-weight:500\">Tu negocio</p></div>\n<div style=\"display:flex;flex-direction:column;gap:8px;padding:32px 32px 32px 0px;border-bottom:1px solid #E2E2DE\"><p style=\"font-size:24px;color:#8A8A8F\">02</p><p style=\"font-size:32px;font-weight:500\">La necesidad</p></div>\n<div style=\"display:flex;flex-direction:column;gap:8px;padding:32px 32px 32px 0px;border-bottom:1px solid #E2E2DE\"><p style=\"font-size:24px;color:#8A8A8F\">03</p><p style=\"font-size:32px;font-weight:500\">La aplicación</p></div>\n<div style=\"display:flex;flex-direction:column;gap:8px;padding:32px 32px 32px 0px;border-bottom:1px solid #E2E2DE\"><p style=\"font-size:24px;color:#8A8A8F\">04</p><p style=\"font-size:32px;font-weight:500\">Funciones</p></div>\n<div style=\"display:flex;flex-direction:column;gap:8px;padding:32px 32px 32px 0px;border-bottom:1px solid #E2E2DE\"><p style=\"font-size:24px;color:#8A8A8F\">05</p><p style=\"font-size:32px;font-weight:500\">Cómo funciona</p></div>\n<div style=\"display:flex;flex-direction:column;gap:8px;padding:32px 32px 32px 0px;border-bottom:1px solid #E2E2DE\"><p style=\"font-size:24px;color:#8A8A8F\">06</p><p style=\"font-size:32px;font-weight:500\">Cómo se vería</p></div>\n<div style=\"display:flex;flex-direction:column;gap:8px;padding:32px 32px 32px 0px;border-bottom:1px solid #E2E2DE\"><p style=\"font-size:24px;color:#8A8A8F\">07</p><p style=\"font-size:32px;font-weight:500\">Inversión</p></div>\n<div style=\"display:flex;flex-direction:column;gap:8px;padding:32px 32px 32px 0px;border-bottom:1px solid #E2E2DE\"><p style=\"font-size:24px;color:#8A8A8F\">08</p><p style=\"font-size:32px;font-weight:500\">Qué incluye</p></div>\n<div style=\"display:flex;flex-direction:column;gap:8px;padding:32px 32px 32px 0px;border-bottom:1px solid #E2E2DE\"><p style=\"font-size:24px;color:#8A8A8F\">09</p><p style=\"font-size:32px;font-weight:500\">Siguientes pasos</p></div>\n</div>\n<img id=\"ark-logo\" src=\"propuesta/logo-negro.png\" alt=\"ARK\" style=\"position:absolute;left:128px;top:986px;width:43px;height:28px;object-fit:contain\">\n<div id=\"ark-footer\" style=\"position:absolute;left:128px;right:128px;bottom:64px;height:32px;display:flex;flex-direction:row;justify-content:flex-end;align-items:center\"><p style=\"font-size:24px;color:#8A8A8F\">Propuesta para {{cliente_nombre}} · 02</p></div>\n<aside>Presenta la ruta de la llamada para que el cliente sepa qué esperar. Aclara que al final hablaremos de inversión y siguientes pasos, y que puede interrumpir en cualquier momento.</aside>\n</section>"
},
{
"id": "entendimos",
"html": "<section id=\"entendimos\" data-transition=\"magic\" style=\"background:#FAFAF8;color:#0E0E0F;font-family:'Inter', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:64px\">\n<p data-build-in=\"fade 1 auto\" style=\"position:absolute;left:128px;top:128px;width:1664px;font-size:24px;letter-spacing:6px;text-transform:uppercase;color:#8A8A8F\">01 — Tu negocio</p>\n<h2 data-build-in=\"rise 1 auto\" style=\"position:absolute;left:128px;top:178px;width:1664px;font-family:'Manrope', Arial, sans-serif;font-size:72px;font-weight:500;line-height:1.1;letter-spacing:-1.5px\">Lo que entendimos de {{cliente_nombre}}</h2>\n<div data-build-in=\"rise 2 auto\" style=\"position:absolute;left:128px;top:321px;width:960px;display:flex;flex-direction:column;gap:24px\">\n<p style=\"font-size:32px;line-height:1.5;color:#2A2A2D\">{{resumen_negocio}}</p>\n<p style=\"font-size:24px;line-height:1.5;color:#55555A\">{{contexto_adicional}}</p>\n</div>\n<div data-build-in=\"rise 3 auto\" style=\"position:absolute;left:1152px;top:321px;width:640px;display:flex;flex-direction:column;border-top:1px solid #E2E2DE\">\n<div data-vars=\"cliente_industria\" style=\"display:flex;justify-content:space-between;gap:24px;padding:24px 0px;border-bottom:1px solid #E2E2DE\"><p style=\"font-size:24px;color:#8A8A8F\">Industria</p><p style=\"font-size:24px;font-weight:600;text-align:right\">{{cliente_industria}}</p></div>\n<div data-vars=\"cliente_tamano\" style=\"display:flex;justify-content:space-between;gap:24px;padding:24px 0px;border-bottom:1px solid #E2E2DE\"><p style=\"font-size:24px;color:#8A8A8F\">Tamaño</p><p style=\"font-size:24px;font-weight:600;text-align:right\">{{cliente_tamano}}</p></div>\n<div data-vars=\"cliente_ubicacion\" style=\"display:flex;justify-content:space-between;gap:24px;padding:24px 0px;border-bottom:1px solid #E2E2DE\"><p style=\"font-size:24px;color:#8A8A8F\">Ubicación</p><p style=\"font-size:24px;font-weight:600;text-align:right\">{{cliente_ubicacion}}</p></div>\n<div data-vars=\"operacion_actual\" style=\"display:flex;justify-content:space-between;gap:24px;padding:24px 0px;border-bottom:1px solid #E2E2DE\"><p style=\"font-size:24px;color:#8A8A8F\">Cómo operan hoy</p><p style=\"font-size:24px;font-weight:600;text-align:right\">{{operacion_actual}}</p></div>\n<div data-vars=\"objetivo_cliente\" style=\"display:flex;justify-content:space-between;gap:24px;padding:24px 0px;border-bottom:1px solid #E2E2DE\"><p style=\"font-size:24px;color:#8A8A8F\">Objetivo</p><p style=\"font-size:24px;font-weight:600;text-align:right\">{{objetivo_cliente}}</p></div>\n</div>\n<img id=\"ark-logo\" src=\"propuesta/logo-negro.png\" alt=\"ARK\" style=\"position:absolute;left:128px;top:986px;width:43px;height:28px;object-fit:contain\">\n<div id=\"ark-footer\" style=\"position:absolute;left:128px;right:128px;bottom:64px;height:32px;display:flex;flex-direction:row;justify-content:flex-end;align-items:center\"><p style=\"font-size:24px;color:#8A8A8F\">Propuesta para {{cliente_nombre}} · 03</p></div>\n<aside>Repite con tus palabras lo que el cliente contó en la primera llamada o en la encuesta. Pregunta: \"¿Lo entendimos bien? ¿Falta algo?\" Esto genera confianza antes de proponer. Variables: resumen_negocio (2–3 frases), contexto_adicional, cliente_industria, cliente_tamano, cliente_ubicacion, operacion_actual (ej. \"Excel y WhatsApp\"), objetivo_cliente.</aside>\n</section>"
},
{
"id": "necesidad",
"html": "<section id=\"necesidad\" data-transition=\"magic\" style=\"background:#0E0E0F;color:#FAFAF8;font-family:'Inter', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;justify-content:space-between;gap:48px\">\n<p data-build-in=\"fade 1 auto\" style=\"position:absolute;left:128px;top:128px;width:1664px;font-size:24px;letter-spacing:6px;text-transform:uppercase;color:#A1A1A6\">02 — La necesidad que detectamos</p>\n<h2 data-build-in=\"rise 2 auto\" style=\"position:absolute;left:128px;top:482px;width:1500px;transform:translateY(-50%);font-family:'Manrope', Arial, sans-serif;font-size:72px;font-weight:300;line-height:1.15;letter-spacing:-1.5px\">“{{necesidad_principal}}”</h2>\n<div data-build-in=\"rise 3 auto\" style=\"position:absolute;left:128px;bottom:160px;width:1664px;display:flex;gap:32px\">\n<div data-vars=\"dolor_1\" style=\"flex:1;display:flex;flex-direction:column;gap:12px;padding:32px 0px 0px 0px;border-top:1px solid #3A3A3E\"><p style=\"font-size:24px;color:#77777C\">Problema 01</p><p style=\"font-size:28px;line-height:1.4;color:#E4E4E6\">{{dolor_1}}</p></div>\n<div data-vars=\"dolor_2\" style=\"flex:1;display:flex;flex-direction:column;gap:12px;padding:32px 0px 0px 0px;border-top:1px solid #3A3A3E\"><p style=\"font-size:24px;color:#77777C\">Problema 02</p><p style=\"font-size:28px;line-height:1.4;color:#E4E4E6\">{{dolor_2}}</p></div>\n<div data-vars=\"dolor_3\" style=\"flex:1;display:flex;flex-direction:column;gap:12px;padding:32px 0px 0px 0px;border-top:1px solid #3A3A3E\"><p style=\"font-size:24px;color:#77777C\">Problema 03</p><p style=\"font-size:28px;line-height:1.4;color:#E4E4E6\">{{dolor_3}}</p></div>\n</div>\n<img id=\"ark-logo\" src=\"propuesta/logo-blanco.png\" alt=\"ARK\" style=\"position:absolute;left:128px;top:986px;width:43px;height:28px;object-fit:contain\">\n<div id=\"ark-footer\" style=\"position:absolute;left:128px;right:128px;bottom:64px;height:32px;display:flex;flex-direction:row;justify-content:flex-end;align-items:center\"><p style=\"font-size:24px;color:#77777C\">Propuesta para {{cliente_nombre}} · 04</p></div>\n<aside>Este es el momento clave: nombra el problema en una frase clara y deja una pausa. Luego explica los tres síntomas concretos. Variables: necesidad_principal (una frase, idealmente con palabras del cliente), dolor_1, dolor_2, dolor_3.</aside>\n</section>"
},
{
"id": "oportunidad",
"html": "<section id=\"oportunidad\" data-transition=\"magic\" style=\"background:#FAFAF8;color:#0E0E0F;font-family:'Inter', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;justify-content:space-between;gap:48px\">\n<p data-build-in=\"fade 1 auto\" style=\"position:absolute;left:128px;top:128px;width:1664px;font-size:24px;letter-spacing:6px;text-transform:uppercase;color:#8A8A8F\">02 — La oportunidad</p>\n<h2 data-build-in=\"rise 1 auto\" style=\"position:absolute;left:128px;top:178px;width:1664px;font-family:'Manrope', Arial, sans-serif;font-size:72px;font-weight:500;line-height:1.1;letter-spacing:-1.5px\">Lo que cambia si lo resolvemos</h2>\n<div data-build-in=\"rise 2 auto\" style=\"position:absolute;left:128px;top:572px;width:1664px;transform:translateY(-50%);display:flex;gap:32px\">\n<div data-vars=\"impacto_1_valor impacto_1_texto\" style=\"flex:1;display:flex;flex-direction:column;gap:16px;background:#FFFFFF;border:1px solid #E2E2DE;border-radius:24px;padding:48px\">\n<p style=\"font-family:'Manrope', Arial, sans-serif;font-size:120px;font-weight:300;line-height:1;letter-spacing:-3px\">{{impacto_1_valor}}</p>\n<p style=\"font-size:28px;line-height:1.4;color:#55555A\">{{impacto_1_texto}}</p>\n</div>\n<div data-vars=\"impacto_2_valor impacto_2_texto\" style=\"flex:1;display:flex;flex-direction:column;gap:16px;background:#FFFFFF;border:1px solid #E2E2DE;border-radius:24px;padding:48px\">\n<p style=\"font-family:'Manrope', Arial, sans-serif;font-size:120px;font-weight:300;line-height:1;letter-spacing:-3px\">{{impacto_2_valor}}</p>\n<p style=\"font-size:28px;line-height:1.4;color:#55555A\">{{impacto_2_texto}}</p>\n</div>\n<div data-vars=\"impacto_3_valor impacto_3_texto\" style=\"flex:1;display:flex;flex-direction:column;gap:16px;background:#0E0E0F;color:#FAFAF8;border-radius:24px;padding:48px\">\n<p style=\"font-family:'Manrope', Arial, sans-serif;font-size:120px;font-weight:300;line-height:1;letter-spacing:-3px\">{{impacto_3_valor}}</p>\n<p style=\"font-size:28px;line-height:1.4;color:#C9C9CC\">{{impacto_3_texto}}</p>\n</div>\n</div>\n<p data-build-in=\"fade 3 auto\" style=\"position:absolute;left:128px;bottom:160px;width:1664px;font-size:24px;color:#8A8A8F\">{{nota_estimacion}}</p>\n<img id=\"ark-logo\" src=\"propuesta/logo-negro.png\" alt=\"ARK\" style=\"position:absolute;left:128px;top:986px;width:43px;height:28px;object-fit:contain\">\n<div id=\"ark-footer\" style=\"position:absolute;left:128px;right:128px;bottom:64px;height:32px;display:flex;flex-direction:row;justify-content:flex-end;align-items:center\"><p style=\"font-size:24px;color:#8A8A8F\">Propuesta para {{cliente_nombre}} · 05</p></div>\n<aside>Traduce el problema a resultados. Usa cifras solo si vienen del cliente o de una estimación razonable explicada; si no, usa beneficios cualitativos cortos (ej. \"0 hojas de Excel\"). Variables: impacto_1_valor / impacto_1_texto (ej. \"-10 h\" / \"a la semana en captura manual\"), impacto_2, impacto_3, nota_estimacion (ej. \"Estimaciones basadas en lo que nos compartiste\").</aside>\n</section>"
},
{
"id": "solucion",
"html": "<section id=\"solucion\" data-transition=\"magic\" style=\"background:#F1F1EE;color:#0E0E0F;font-family:'Inter', Arial, sans-serif;padding:128px 128px 160px;display:grid;grid-template-columns:1fr 600px;gap:96px;align-items:center\">\n<div data-build-in=\"rise 1 auto\" style=\"position:absolute;left:128px;top:524px;width:968px;transform:translateY(-50%);display:flex;flex-direction:column;gap:40px\">\n<p style=\"font-size:24px;letter-spacing:6px;text-transform:uppercase;color:#8A8A8F\">03 — Nuestra propuesta</p>\n<h2 style=\"font-family:'Manrope', Arial, sans-serif;font-size:96px;font-weight:500;line-height:1.05;letter-spacing:-2.5px\">{{nombre_app}}</h2>\n<p style=\"font-size:32px;line-height:1.45;color:#2A2A2D\">{{descripcion_app}}</p>\n<div style=\"display:flex;flex-wrap:wrap;gap:16px\">\n<p data-vars=\"plataforma_1\" style=\"font-size:24px;padding:12px 28px;border:1px solid #0E0E0F;border-radius:999px\">{{plataforma_1}}</p>\n<p data-vars=\"plataforma_2\" style=\"font-size:24px;padding:12px 28px;border:1px solid #0E0E0F;border-radius:999px\">{{plataforma_2}}</p>\n<p data-vars=\"plataforma_3\" style=\"font-size:24px;padding:12px 28px;border:1px solid #0E0E0F;border-radius:999px\">{{plataforma_3}}</p>\n</div>\n</div>\n<div data-build-in=\"rise 2 auto\" style=\"position:absolute;left:1192px;top:524px;width:600px;transform:translateY(-50%);display:flex;flex-direction:column;gap:0px;background:#FFFFFF;border-radius:32px;padding:48px\">\n<p style=\"font-size:24px;letter-spacing:4px;text-transform:uppercase;color:#8A8A8F\">¿Quién la usa?</p>\n<div data-vars=\"usuario_1 usuario_1_uso\" style=\"display:flex;flex-direction:column;gap:6px;padding:28px 0px;border-bottom:1px solid #E2E2DE\"><p style=\"font-size:28px;font-weight:600\">{{usuario_1}}</p><p style=\"font-size:24px;line-height:1.4;color:#55555A\">{{usuario_1_uso}}</p></div>\n<div data-vars=\"usuario_2 usuario_2_uso\" style=\"display:flex;flex-direction:column;gap:6px;padding:28px 0px;border-bottom:1px solid #E2E2DE\"><p style=\"font-size:28px;font-weight:600\">{{usuario_2}}</p><p style=\"font-size:24px;line-height:1.4;color:#55555A\">{{usuario_2_uso}}</p></div>\n<div data-vars=\"usuario_3 usuario_3_uso\" style=\"display:flex;flex-direction:column;gap:6px;padding:28px 0px 0px 0px\"><p style=\"font-size:28px;font-weight:600\">{{usuario_3}}</p><p style=\"font-size:24px;line-height:1.4;color:#55555A\">{{usuario_3_uso}}</p></div>\n</div>\n<img id=\"ark-logo\" src=\"propuesta/logo-negro.png\" alt=\"ARK\" style=\"position:absolute;left:128px;top:986px;width:43px;height:28px;object-fit:contain\">\n<div id=\"ark-footer\" style=\"position:absolute;left:128px;right:128px;bottom:64px;height:32px;display:flex;flex-direction:row;justify-content:flex-end;align-items:center\"><p style=\"font-size:24px;color:#8A8A8F\">Propuesta para {{cliente_nombre}} · 06</p></div>\n<aside>Presenta la app por su nombre, como un producto propio del cliente. Variables: nombre_app, descripcion_app (2 frases: qué es y qué resuelve), plataforma_1..3 (ej. \"App iOS\", \"App Android\", \"Panel web\"), usuario_1..3 y su uso (ej. \"Dueño\" / \"Ve ventas y reportes en tiempo real\").</aside>\n</section>"
},
{
"id": "funciones",
"html": "<section id=\"funciones\" data-transition=\"magic\" style=\"background:#FAFAF8;color:#0E0E0F;font-family:'Inter', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<p data-build-in=\"fade 1 auto\" style=\"position:absolute;left:128px;top:128px;width:1664px;font-size:24px;letter-spacing:6px;text-transform:uppercase;color:#8A8A8F\">04 — Funciones</p>\n<h2 data-build-in=\"rise 1 auto\" style=\"position:absolute;left:128px;top:178px;width:1664px;font-family:'Manrope', Arial, sans-serif;font-size:72px;font-weight:500;line-height:1.1;letter-spacing:-1.5px\">Lo que hará {{nombre_app}}</h2>\n<div data-build-in=\"rise 2 auto\" style=\"position:absolute;left:128px;top:313px;width:1664px;display:grid;grid-template-columns:1fr 1fr 1fr;gap:24px\">\n<div data-vars=\"funcion_1 funcion_1_desc\" style=\"display:flex;flex-direction:column;gap:16px;background:#FFFFFF;border:1px solid #E2E2DE;border-radius:24px;padding:36px\"><x-icon name=\"Users\" style=\"color:#0E0E0F;width:40px;height:40px\"></x-icon><h3 style=\"font-family:'Manrope', Arial, sans-serif;font-size:32px;font-weight:600\">{{funcion_1}}</h3><p style=\"font-size:24px;line-height:1.4;color:#55555A\">{{funcion_1_desc}}</p></div>\n<div data-vars=\"funcion_2 funcion_2_desc\" style=\"display:flex;flex-direction:column;gap:16px;background:#FFFFFF;border:1px solid #E2E2DE;border-radius:24px;padding:36px\"><x-icon name=\"Clock\" style=\"color:#0E0E0F;width:40px;height:40px\"></x-icon><h3 style=\"font-family:'Manrope', Arial, sans-serif;font-size:32px;font-weight:600\">{{funcion_2}}</h3><p style=\"font-size:24px;line-height:1.4;color:#55555A\">{{funcion_2_desc}}</p></div>\n<div data-vars=\"funcion_3 funcion_3_desc\" style=\"display:flex;flex-direction:column;gap:16px;background:#FFFFFF;border:1px solid #E2E2DE;border-radius:24px;padding:36px\"><x-icon name=\"Chart\" style=\"color:#0E0E0F;width:40px;height:40px\"></x-icon><h3 style=\"font-family:'Manrope', Arial, sans-serif;font-size:32px;font-weight:600\">{{funcion_3}}</h3><p style=\"font-size:24px;line-height:1.4;color:#55555A\">{{funcion_3_desc}}</p></div>\n<div data-vars=\"funcion_4 funcion_4_desc\" style=\"display:flex;flex-direction:column;gap:16px;background:#FFFFFF;border:1px solid #E2E2DE;border-radius:24px;padding:36px\"><x-icon name=\"Chat\" style=\"color:#0E0E0F;width:40px;height:40px\"></x-icon><h3 style=\"font-family:'Manrope', Arial, sans-serif;font-size:32px;font-weight:600\">{{funcion_4}}</h3><p style=\"font-size:24px;line-height:1.4;color:#55555A\">{{funcion_4_desc}}</p></div>\n<div data-vars=\"funcion_5 funcion_5_desc\" style=\"display:flex;flex-direction:column;gap:16px;background:#FFFFFF;border:1px solid #E2E2DE;border-radius:24px;padding:36px\"><x-icon name=\"Lock\" style=\"color:#0E0E0F;width:40px;height:40px\"></x-icon><h3 style=\"font-family:'Manrope', Arial, sans-serif;font-size:32px;font-weight:600\">{{funcion_5}}</h3><p style=\"font-size:24px;line-height:1.4;color:#55555A\">{{funcion_5_desc}}</p></div>\n<div data-vars=\"funcion_6 funcion_6_desc\" style=\"display:flex;flex-direction:column;gap:16px;background:#0E0E0F;color:#FAFAF8;border-radius:24px;padding:36px\"><x-icon name=\"Lightning\" style=\"color:#FAFAF8;width:40px;height:40px\"></x-icon><h3 style=\"font-family:'Manrope', Arial, sans-serif;font-size:32px;font-weight:600\">{{funcion_6}}</h3><p style=\"font-size:24px;line-height:1.4;color:#C9C9CC\">{{funcion_6_desc}}</p></div>\n</div>\n<img id=\"ark-logo\" src=\"propuesta/logo-negro.png\" alt=\"ARK\" style=\"position:absolute;left:128px;top:986px;width:43px;height:28px;object-fit:contain\">\n<div id=\"ark-footer\" style=\"position:absolute;left:128px;right:128px;bottom:64px;height:32px;display:flex;flex-direction:row;justify-content:flex-end;align-items:center\"><p style=\"font-size:24px;color:#8A8A8F\">Propuesta para {{cliente_nombre}} · 07</p></div>\n<aside>Recorre las seis funciones, conectando cada una con un problema de la diapositiva 04. La tarjeta negra es la función estrella o diferenciadora. Cambia los íconos si hace falta (Users, Clock, Chart, Chat, Lock, Lightning, Database, Globe, Settings, etc.). Variables: funcion_1..6 (2–4 palabras) y funcion_1..6_desc (una frase).</aside>\n</section>"
},
{
"id": "flujo",
"html": "<section id=\"flujo\" data-transition=\"magic\" style=\"background:#FAFAF8;color:#0E0E0F;font-family:'Inter', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;justify-content:space-between;gap:48px\">\n<p data-build-in=\"fade 1 auto\" style=\"position:absolute;left:128px;top:128px;width:1664px;font-size:24px;letter-spacing:6px;text-transform:uppercase;color:#8A8A8F\">05 — Cómo funciona</p>\n<h2 data-build-in=\"rise 1 auto\" style=\"position:absolute;left:128px;top:178px;width:1664px;font-family:'Manrope', Arial, sans-serif;font-size:72px;font-weight:500;line-height:1.1;letter-spacing:-1.5px\">Un día con {{nombre_app}}</h2>\n<div data-build-in=\"rise 2 auto\" style=\"position:absolute;left:128px;top:569px;width:1664px;transform:translateY(-50%);display:flex;flex-direction:row;align-items:center;gap:16px\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:20px;background:#FFFFFF;border:1px solid #E2E2DE;border-radius:24px;padding:36px\">\n<p style=\"font-family:'Manrope', Arial, sans-serif;font-size:44px;font-weight:300;color:#8A8A8F\">01</p>\n<h3 style=\"font-family:'Manrope', Arial, sans-serif;font-size:32px;font-weight:600\">{{paso_1}}</h3>\n<p style=\"font-size:24px;line-height:1.4;color:#55555A\">{{paso_1_desc}}</p>\n</div>\n<x-connector style=\"width:48px;color:#0E0E0F;border-width:2px\"></x-connector>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:20px;background:#FFFFFF;border:1px solid #E2E2DE;border-radius:24px;padding:36px\">\n<p style=\"font-family:'Manrope', Arial, sans-serif;font-size:44px;font-weight:300;color:#8A8A8F\">02</p>\n<h3 style=\"font-family:'Manrope', Arial, sans-serif;font-size:32px;font-weight:600\">{{paso_2}}</h3>\n<p style=\"font-size:24px;line-height:1.4;color:#55555A\">{{paso_2_desc}}</p>\n</div>\n<x-connector style=\"width:48px;color:#0E0E0F;border-width:2px\"></x-connector>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:20px;background:#FFFFFF;border:1px solid #E2E2DE;border-radius:24px;padding:36px\">\n<p style=\"font-family:'Manrope', Arial, sans-serif;font-size:44px;font-weight:300;color:#8A8A8F\">03</p>\n<h3 style=\"font-family:'Manrope', Arial, sans-serif;font-size:32px;font-weight:600\">{{paso_3}}</h3>\n<p style=\"font-size:24px;line-height:1.4;color:#55555A\">{{paso_3_desc}}</p>\n</div>\n<x-connector style=\"width:48px;color:#0E0E0F;border-width:2px\"></x-connector>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:20px;background:#0E0E0F;color:#FAFAF8;border-radius:24px;padding:36px\">\n<p style=\"font-family:'Manrope', Arial, sans-serif;font-size:44px;font-weight:300;color:#A1A1A6\">04</p>\n<h3 style=\"font-family:'Manrope', Arial, sans-serif;font-size:32px;font-weight:600\">{{paso_4}}</h3>\n<p style=\"font-size:24px;line-height:1.4;color:#C9C9CC\">{{paso_4_desc}}</p>\n</div>\n</div>\n<p data-build-in=\"fade 3 auto\" style=\"position:absolute;left:128px;bottom:160px;width:1300px;font-size:28px;line-height:1.4;color:#2A2A2D\"><b>Resultado:</b> {{resultado_flujo}}</p>\n<img id=\"ark-logo\" src=\"propuesta/logo-negro.png\" alt=\"ARK\" style=\"position:absolute;left:128px;top:986px;width:43px;height:28px;object-fit:contain\">\n<div id=\"ark-footer\" style=\"position:absolute;left:128px;right:128px;bottom:64px;height:32px;display:flex;flex-direction:row;justify-content:flex-end;align-items:center\"><p style=\"font-size:24px;color:#8A8A8F\">Propuesta para {{cliente_nombre}} · 08</p></div>\n<aside>Cuenta el flujo como una historia: quién hace qué, en qué orden, y qué obtiene el negocio al final. Variables: paso_1..4 (2–4 palabras, ej. \"El cliente reserva\"), paso_1..4_desc (una frase), resultado_flujo (una frase con el beneficio final).</aside>\n</section>"
},
{
"id": "concepto",
"html": "<section id=\"concepto\" data-transition=\"magic\" style=\"background:#F1F1EE;color:#0E0E0F;font-family:'Inter', Arial, sans-serif;padding:128px 128px 160px;display:grid;grid-template-columns:480px 1fr;gap:96px;align-items:center\">\n<div data-build-in=\"rise 1 auto\" style=\"position:absolute;left:128px;top:524px;width:480px;transform:translateY(-50%);display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:24px;letter-spacing:6px;text-transform:uppercase;color:#8A8A8F\">06 — Concepto visual</p>\n<h2 style=\"font-family:'Manrope', Arial, sans-serif;font-size:72px;font-weight:500;line-height:1.1;letter-spacing:-1.5px\">Así se vería</h2>\n<p style=\"font-size:28px;line-height:1.45;color:#2A2A2D\">{{descripcion_visual}}</p>\n<p style=\"font-size:24px;line-height:1.4;color:#8A8A8F\">Diseño conceptual. La interfaz final se define contigo en la fase de diseño.</p>\n</div>\n<div data-build-in=\"rise 2 auto\" style=\"position:absolute;left:704px;top:524px;width:336px;transform:translateY(-50%);display:flex;flex-direction:column;align-items:center;gap:24px\">\n<div style=\"width:280px;height:572px;display:flex;flex-direction:column;gap:14px;background:#FFFFFF;border:10px solid #0E0E0F;border-radius:48px;padding:28px 20px;box-shadow:0px 32px 64px rgba(14,14,15,0.18)\">\n<div style=\"width:72px;height:10px;background:#0E0E0F;border-radius:999px;align-self:center\"></div>\n<div style=\"width:150px;height:18px;background:#0E0E0F;border-radius:6px\"></div>\n<div style=\"width:100px;height:12px;background:#D6D6D2;border-radius:6px\"></div>\n<div style=\"height:140px;background:#0E0E0F;border-radius:18px\"></div>\n<div style=\"height:64px;background:#F1F1EE;border-radius:14px\"></div>\n<div style=\"height:64px;background:#F1F1EE;border-radius:14px\"></div>\n<div style=\"height:64px;background:#F1F1EE;border-radius:14px\"></div>\n</div>\n<p style=\"font-size:24px;font-weight:600;text-align:center\">{{pantalla_1}}</p>\n</div>\n<div data-build-in=\"rise 3 auto\" style=\"position:absolute;left:1080px;top:524px;width:336px;transform:translateY(-50%);display:flex;flex-direction:column;align-items:center;gap:24px\">\n<div style=\"width:280px;height:572px;display:flex;flex-direction:column;gap:14px;background:#FFFFFF;border:10px solid #0E0E0F;border-radius:48px;padding:28px 20px;box-shadow:0px 32px 64px rgba(14,14,15,0.18)\">\n<div style=\"width:72px;height:10px;background:#0E0E0F;border-radius:999px;align-self:center\"></div>\n<div style=\"width:120px;height:18px;background:#0E0E0F;border-radius:6px\"></div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:12px\">\n<div style=\"height:96px;background:#F1F1EE;border-radius:14px\"></div>\n<div style=\"height:96px;background:#F1F1EE;border-radius:14px\"></div>\n<div style=\"height:96px;background:#F1F1EE;border-radius:14px\"></div>\n<div style=\"height:96px;background:#0E0E0F;border-radius:14px\"></div>\n</div>\n<div style=\"height:120px;background:#F1F1EE;border-radius:14px\"></div>\n<div style=\"height:48px;background:#0E0E0F;border-radius:999px\"></div>\n</div>\n<p style=\"font-size:24px;font-weight:600;text-align:center\">{{pantalla_2}}</p>\n</div>\n<div data-build-in=\"rise 4 auto\" style=\"position:absolute;left:1456px;top:524px;width:336px;transform:translateY(-50%);display:flex;flex-direction:column;align-items:center;gap:24px\">\n<div style=\"width:280px;height:572px;display:flex;flex-direction:column;gap:14px;background:#0E0E0F;border:10px solid #0E0E0F;border-radius:48px;padding:28px 20px;box-shadow:0px 32px 64px rgba(14,14,15,0.18)\">\n<div style=\"width:72px;height:10px;background:#3A3A3E;border-radius:999px;align-self:center\"></div>\n<div style=\"width:140px;height:18px;background:#FAFAF8;border-radius:6px\"></div>\n<div style=\"width:90px;height:12px;background:#55555A;border-radius:6px\"></div>\n<div style=\"height:180px;background:linear-gradient(180deg, #3A3A3E 0%, #1C1C1E 100%);border-radius:18px\"></div>\n<div style=\"height:56px;background:#1C1C1E;border-radius:14px\"></div>\n<div style=\"height:56px;background:#1C1C1E;border-radius:14px\"></div>\n<div style=\"height:48px;background:#FAFAF8;border-radius:999px\"></div>\n</div>\n<p style=\"font-size:24px;font-weight:600;text-align:center\">{{pantalla_3}}</p>\n</div>\n<img id=\"ark-logo\" src=\"propuesta/logo-negro.png\" alt=\"ARK\" style=\"position:absolute;left:128px;top:986px;width:43px;height:28px;object-fit:contain\">\n<div id=\"ark-footer\" style=\"position:absolute;left:128px;right:128px;bottom:64px;height:32px;display:flex;flex-direction:row;justify-content:flex-end;align-items:center\"><p style=\"font-size:24px;color:#8A8A8F\">Propuesta para {{cliente_nombre}} · 09</p></div>\n<aside>Muestra la idea visual sin comprometer el diseño final. Si ya tienes mockups reales del cliente, reemplaza cada teléfono por una imagen (mismo tamaño, 280×572). Variables: descripcion_visual (estilo, colores de la marca del cliente, sensación), pantalla_1..3 (ej. \"Inicio\", \"Reservas\", \"Reportes\").</aside>\n</section>"
},
{
"id": "plan",
"html": "<section id=\"plan\" data-transition=\"magic\" style=\"background:#FAFAF8;color:#0E0E0F;font-family:'Inter', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;justify-content:space-between;gap:48px\">\n<div data-build-in=\"rise 1 auto\" style=\"position:absolute;left:128px;top:128px;width:1664px;display:flex;flex-direction:row;justify-content:space-between;align-items:end\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;letter-spacing:6px;text-transform:uppercase;color:#8A8A8F\">07 — Plan de trabajo</p>\n<h2 style=\"font-family:'Manrope', Arial, sans-serif;font-size:72px;font-weight:500;line-height:1.1;letter-spacing:-1.5px\">De la idea a tu app</h2>\n</div>\n<p style=\"font-size:28px;padding:14px 32px;background:#0E0E0F;color:#FAFAF8;border-radius:999px\">Entrega estimada: {{tiempo_total}}</p>\n</div>\n<div data-build-in=\"rise 2 auto\" style=\"position:absolute;left:128px;top:572px;width:1664px;transform:translateY(-50%);display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:0px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;padding:32px 32px 0px 0px;border-top:4px solid #0E0E0F\"><p style=\"font-size:24px;color:#8A8A8F\">{{fase_1_tiempo}}</p><h3 style=\"font-family:'Manrope', Arial, sans-serif;font-size:32px;font-weight:600\">Descubrimiento</h3><p style=\"font-size:24px;line-height:1.4;color:#55555A\">{{fase_1_desc}}</p></div>\n<div style=\"display:flex;flex-direction:column;gap:16px;padding:32px 32px 0px 0px;border-top:4px solid #55555A\"><p style=\"font-size:24px;color:#8A8A8F\">{{fase_2_tiempo}}</p><h3 style=\"font-family:'Manrope', Arial, sans-serif;font-size:32px;font-weight:600\">Diseño</h3><p style=\"font-size:24px;line-height:1.4;color:#55555A\">{{fase_2_desc}}</p></div>\n<div style=\"display:flex;flex-direction:column;gap:16px;padding:32px 32px 0px 0px;border-top:4px solid #A1A1A6\"><p style=\"font-size:24px;color:#8A8A8F\">{{fase_3_tiempo}}</p><h3 style=\"font-family:'Manrope', Arial, sans-serif;font-size:32px;font-weight:600\">Desarrollo</h3><p style=\"font-size:24px;line-height:1.4;color:#55555A\">{{fase_3_desc}}</p></div>\n<div style=\"display:flex;flex-direction:column;gap:16px;padding:32px 32px 0px 0px;border-top:4px solid #D6D6D2\"><p style=\"font-size:24px;color:#8A8A8F\">{{fase_4_tiempo}}</p><h3 style=\"font-family:'Manrope', Arial, sans-serif;font-size:32px;font-weight:600\">Lanzamiento</h3><p style=\"font-size:24px;line-height:1.4;color:#55555A\">{{fase_4_desc}}</p></div>\n</div>\n<p data-build-in=\"fade 3 auto\" style=\"position:absolute;left:128px;bottom:160px;width:1300px;font-size:24px;line-height:1.4;color:#8A8A8F\">Revisiones contigo al cierre de cada fase. Avances visibles cada semana.</p>\n<img id=\"ark-logo\" src=\"propuesta/logo-negro.png\" alt=\"ARK\" style=\"position:absolute;left:128px;top:986px;width:43px;height:28px;object-fit:contain\">\n<div id=\"ark-footer\" style=\"position:absolute;left:128px;right:128px;bottom:64px;height:32px;display:flex;flex-direction:row;justify-content:flex-end;align-items:center\"><p style=\"font-size:24px;color:#8A8A8F\">Propuesta para {{cliente_nombre}} · 10</p></div>\n<aside>Explica que el proceso es ordenado y transparente. Variables: tiempo_total (ej. \"8 semanas\"), fase_1..4_tiempo (ej. \"Semana 1\"), fase_1..4_desc (una frase de qué pasa en cada fase).</aside>\n</section>"
},
{
"id": "inversion",
"html": "<section id=\"inversion\" data-transition=\"magic\" style=\"background:#0E0E0F;color:#FAFAF8;font-family:'Inter', Arial, sans-serif;padding:128px 128px 160px;display:grid;grid-template-columns:1fr 640px;gap:96px;align-items:center\">\n<div data-build-in=\"rise 1 auto\" style=\"position:absolute;left:128px;top:524px;width:928px;transform:translateY(-50%);display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:24px;letter-spacing:6px;text-transform:uppercase;color:#A1A1A6\">08 — Inversión</p>\n<p style=\"font-size:28px;color:#C9C9CC\">Desarrollo completo de {{nombre_app}}</p>\n<p style=\"font-family:'Manrope', Arial, sans-serif;font-size:160px;font-weight:300;line-height:1;letter-spacing:-5px\">{{precio_total}}</p>\n<p style=\"font-size:28px;color:#A1A1A6\">{{moneda}} · {{impuestos_nota}}</p>\n<div style=\"display:flex;gap:16px;align-items:center;padding:24px 32px;border:1px solid #3A3A3E;border-radius:20px;width:820px\">\n<p style=\"font-size:28px;font-weight:600\">+ {{precio_mensual}} / mes</p>\n<p style=\"font-size:24px;color:#A1A1A6\">{{mensualidad_concepto}}</p>\n</div>\n</div>\n<div data-build-in=\"rise 2 auto\" style=\"position:absolute;left:1152px;top:524px;width:640px;transform:translateY(-50%);display:flex;flex-direction:column;gap:0px;background:#1C1C1E;border-radius:32px;padding:48px\">\n<p style=\"font-size:24px;letter-spacing:4px;text-transform:uppercase;color:#A1A1A6\">Esquema de pago</p>\n<div style=\"display:flex;justify-content:space-between;gap:24px;padding:28px 0px;border-bottom:1px solid #3A3A3E\"><div style=\"display:flex;flex-direction:column;gap:4px\"><p style=\"font-size:28px;font-weight:600\">{{pago_1_porcentaje}}</p><p style=\"font-size:24px;color:#A1A1A6\">{{pago_1_momento}}</p></div><p style=\"font-size:28px\">{{pago_1_monto}}</p></div>\n<div style=\"display:flex;justify-content:space-between;gap:24px;padding:28px 0px;border-bottom:1px solid #3A3A3E\"><div style=\"display:flex;flex-direction:column;gap:4px\"><p style=\"font-size:28px;font-weight:600\">{{pago_2_porcentaje}}</p><p style=\"font-size:24px;color:#A1A1A6\">{{pago_2_momento}}</p></div><p style=\"font-size:28px\">{{pago_2_monto}}</p></div>\n<div style=\"display:flex;justify-content:space-between;gap:24px;padding:28px 0px 0px 0px\"><div style=\"display:flex;flex-direction:column;gap:4px\"><p style=\"font-size:28px;font-weight:600\">{{pago_3_porcentaje}}</p><p style=\"font-size:24px;color:#A1A1A6\">{{pago_3_momento}}</p></div><p style=\"font-size:28px\">{{pago_3_monto}}</p></div>\n</div>\n<img id=\"ark-logo\" src=\"propuesta/logo-blanco.png\" alt=\"ARK\" style=\"position:absolute;left:128px;top:986px;width:43px;height:28px;object-fit:contain\">\n<div id=\"ark-footer\" style=\"position:absolute;left:128px;right:128px;bottom:64px;height:32px;display:flex;flex-direction:row;justify-content:flex-end;align-items:center\"><p style=\"font-size:24px;color:#77777C\">Vigencia de la propuesta: {{vigencia}} · 11</p></div>\n<aside>Di el precio con seguridad y sin justificarte de más; luego explica el esquema de pago. Si el cliente pregunta por opciones, menciona que se puede ajustar el alcance por fases. Variables: precio_total (ej. \"$85,000\"), moneda (ej. \"MXN\"), impuestos_nota (ej. \"Más IVA\"), precio_mensual y mensualidad_concepto (ej. \"Hosting, soporte y mantenimiento\"), pago_1..3_porcentaje/momento/monto (ej. \"50%\" / \"Al firmar\" / \"$42,500\"), vigencia (ej. \"15 días\").</aside>\n</section>"
},
{
"id": "incluye",
"html": "<section id=\"incluye\" data-transition=\"magic\" style=\"background:#FAFAF8;color:#0E0E0F;font-family:'Inter', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<p data-build-in=\"fade 1 auto\" style=\"position:absolute;left:128px;top:128px;width:1664px;font-size:24px;letter-spacing:6px;text-transform:uppercase;color:#8A8A8F\">09 — Qué incluye</p>\n<h2 data-build-in=\"rise 1 auto\" style=\"position:absolute;left:128px;top:178px;width:1664px;font-family:'Manrope', Arial, sans-serif;font-size:72px;font-weight:500;line-height:1.1;letter-spacing:-1.5px\">Todo lo necesario para lanzar</h2>\n<div data-build-in=\"rise 2 auto\" style=\"position:absolute;left:128px;top:313px;width:1664px;display:grid;grid-template-columns:1fr 1fr 520px;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:0px;border-top:1px solid #E2E2DE\">\n<div style=\"display:flex;gap:16px;align-items:center;padding:22px 0px;border-bottom:1px solid #E2E2DE\"><x-icon name=\"Check\" style=\"color:#0E0E0F;width:32px;height:32px\"></x-icon><p style=\"font-size:26px\">Diseño UX/UI a la medida</p></div>\n<div style=\"display:flex;gap:16px;align-items:center;padding:22px 0px;border-bottom:1px solid #E2E2DE\"><x-icon name=\"Check\" style=\"color:#0E0E0F;width:32px;height:32px\"></x-icon><p style=\"font-size:26px\">Desarrollo de la app</p></div>\n<div style=\"display:flex;gap:16px;align-items:center;padding:22px 0px;border-bottom:1px solid #E2E2DE\"><x-icon name=\"Check\" style=\"color:#0E0E0F;width:32px;height:32px\"></x-icon><p style=\"font-size:26px\">Panel de administración</p></div>\n<div data-vars=\"incluye_extra_1\" style=\"display:flex;gap:16px;align-items:center;padding:22px 0px;border-bottom:1px solid #E2E2DE\"><x-icon name=\"Check\" style=\"color:#0E0E0F;width:32px;height:32px\"></x-icon><p style=\"font-size:26px\">{{incluye_extra_1}}</p></div>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:0px;border-top:1px solid #E2E2DE\">\n<div style=\"display:flex;gap:16px;align-items:center;padding:22px 0px;border-bottom:1px solid #E2E2DE\"><x-icon name=\"Check\" style=\"color:#0E0E0F;width:32px;height:32px\"></x-icon><p style=\"font-size:26px\">Publicación en tiendas</p></div>\n<div style=\"display:flex;gap:16px;align-items:center;padding:22px 0px;border-bottom:1px solid #E2E2DE\"><x-icon name=\"Check\" style=\"color:#0E0E0F;width:32px;height:32px\"></x-icon><p style=\"font-size:26px\">Capacitación a tu equipo</p></div>\n<div style=\"display:flex;gap:16px;align-items:center;padding:22px 0px;border-bottom:1px solid #E2E2DE\"><x-icon name=\"Check\" style=\"color:#0E0E0F;width:32px;height:32px\"></x-icon><p style=\"font-size:26px\">{{garantia}} de garantía</p></div>\n<div data-vars=\"incluye_extra_2\" style=\"display:flex;gap:16px;align-items:center;padding:22px 0px;border-bottom:1px solid #E2E2DE\"><x-icon name=\"Check\" style=\"color:#0E0E0F;width:32px;height:32px\"></x-icon><p style=\"font-size:26px\">{{incluye_extra_2}}</p></div>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#F1F1EE;border-radius:24px;padding:40px\">\n<p style=\"font-size:24px;letter-spacing:4px;text-transform:uppercase;color:#8A8A8F\">No incluye</p>\n<p data-vars=\"no_incluye_1\" style=\"font-size:24px;line-height:1.4;color:#55555A\">— {{no_incluye_1}}</p>\n<p data-vars=\"no_incluye_2\" style=\"font-size:24px;line-height:1.4;color:#55555A\">— {{no_incluye_2}}</p>\n<p data-vars=\"no_incluye_3\" style=\"font-size:24px;line-height:1.4;color:#55555A\">— {{no_incluye_3}}</p>\n</div>\n</div>\n<img id=\"ark-logo\" src=\"propuesta/logo-negro.png\" alt=\"ARK\" style=\"position:absolute;left:128px;top:986px;width:43px;height:28px;object-fit:contain\">\n<div id=\"ark-footer\" style=\"position:absolute;left:128px;right:128px;bottom:64px;height:32px;display:flex;flex-direction:row;justify-content:flex-end;align-items:center\"><p style=\"font-size:24px;color:#8A8A8F\">Propuesta para {{cliente_nombre}} · 12</p></div>\n<aside>Deja claro el alcance para evitar malentendidos. Los seis primeros puntos son estándar de ARK; ajústalos si un proyecto no los lleva (ej. solo web: quitar \"Publicación en tiendas\"). Variables: incluye_extra_1, incluye_extra_2, garantia (ej. \"3 meses\"), no_incluye_1..3 (ej. \"Costos de tiendas de apps\", \"Contenido y fotografías\", \"Integraciones no listadas\").</aside>\n</section>"
},
{
"id": "porque",
"html": "<section id=\"porque\" data-transition=\"magic\" style=\"background:#F1F1EE;color:#0E0E0F;font-family:'Inter', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;justify-content:space-between;gap:48px\">\n<p data-build-in=\"fade 1 auto\" style=\"position:absolute;left:128px;top:128px;width:1664px;font-size:24px;letter-spacing:6px;text-transform:uppercase;color:#8A8A8F\">Por qué ARK</p>\n<h2 data-build-in=\"rise 1 auto\" style=\"position:absolute;left:128px;top:178px;width:1300px;font-family:'Manrope', Arial, sans-serif;font-size:72px;font-weight:500;line-height:1.1;letter-spacing:-1.5px\">Construimos tecnología que se siente hecha para ti</h2>\n<div data-build-in=\"rise 2 auto\" style=\"position:absolute;left:128px;bottom:160px;width:1664px;display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:24px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FFFFFF;border-radius:24px;padding:36px\"><x-icon name=\"Settings\" style=\"color:#0E0E0F;width:40px;height:40px\"></x-icon><h3 style=\"font-family:'Manrope', Arial, sans-serif;font-size:32px;font-weight:600\">A la medida</h3><p style=\"font-size:24px;line-height:1.4;color:#55555A\">Nada de plantillas: cada app nace de cómo opera tu negocio.</p></div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FFFFFF;border-radius:24px;padding:36px\"><x-icon name=\"Star\" style=\"color:#0E0E0F;width:40px;height:40px\"></x-icon><h3 style=\"font-family:'Manrope', Arial, sans-serif;font-size:32px;font-weight:600\">Diseño premium</h3><p style=\"font-size:24px;line-height:1.4;color:#55555A\">Interfaces claras y modernas que tu equipo quiere usar.</p></div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FFFFFF;border-radius:24px;padding:36px\"><x-icon name=\"Chat\" style=\"color:#0E0E0F;width:40px;height:40px\"></x-icon><h3 style=\"font-family:'Manrope', Arial, sans-serif;font-size:32px;font-weight:600\">Cercanía</h3><p style=\"font-size:24px;line-height:1.4;color:#55555A\">Un equipo que responde y te acompaña antes y después del lanzamiento.</p></div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FFFFFF;border-radius:24px;padding:36px\"><x-icon name=\"Trust\" style=\"color:#0E0E0F;width:40px;height:40px\"></x-icon><h3 style=\"font-family:'Manrope', Arial, sans-serif;font-size:32px;font-weight:600\">Tu app es tuya</h3><p style=\"font-size:24px;line-height:1.4;color:#55555A\">Escalable, segura y lista para crecer con tu negocio.</p></div>\n</div>\n<img id=\"ark-logo\" src=\"propuesta/logo-negro.png\" alt=\"ARK\" style=\"position:absolute;left:128px;top:986px;width:43px;height:28px;object-fit:contain\">\n<div id=\"ark-footer\" style=\"position:absolute;left:128px;right:128px;bottom:64px;height:32px;display:flex;flex-direction:row;justify-content:flex-end;align-items:center\"><p style=\"font-size:24px;color:#8A8A8F\">Propuesta para {{cliente_nombre}} · 13</p></div>\n<aside>Diapositiva fija de marca: normalmente no cambia entre prospectos. Revisa que \"Tu app es tuya\" coincida con lo que ARK ofrece en propiedad del código; ajusta si no. Si tienes casos de éxito, este es un buen lugar para mencionarlos.</aside>\n</section>"
},
{
"id": "pasos",
"html": "<section id=\"pasos\" data-transition=\"magic\" style=\"background:#FAFAF8;color:#0E0E0F;font-family:'Inter', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;justify-content:space-between;gap:48px\">\n<p data-build-in=\"fade 1 auto\" style=\"position:absolute;left:128px;top:128px;width:1664px;font-size:24px;letter-spacing:6px;text-transform:uppercase;color:#8A8A8F\">10 — Siguientes pasos</p>\n<h2 data-build-in=\"rise 1 auto\" style=\"position:absolute;left:128px;top:178px;width:1664px;font-family:'Manrope', Arial, sans-serif;font-size:72px;font-weight:500;line-height:1.1;letter-spacing:-1.5px\">Empezamos en cuatro pasos</h2>\n<div data-build-in=\"rise 2 auto\" style=\"position:absolute;left:128px;bottom:515.8px;width:1664px;display:grid;grid-template-columns:120px 1fr 360px;gap:32px;align-items:center;padding:28px 0px;border-top:1px solid #E2E2DE;border-bottom:1px solid #E2E2DE\"><p style=\"font-family:'Manrope', Arial, sans-serif;font-size:44px;font-weight:300;color:#8A8A8F\">01</p><p style=\"font-size:32px;font-weight:500\">Aprobación de la propuesta</p><p style=\"font-size:24px;color:#55555A;text-align:right\">{{paso_siguiente_1_fecha}}</p></div>\n<div data-build-in=\"rise 3 auto\" style=\"position:absolute;left:128px;bottom:397.2px;width:1664px;display:grid;grid-template-columns:120px 1fr 360px;gap:32px;align-items:center;padding:28px 0px;border-bottom:1px solid #E2E2DE\"><p style=\"font-family:'Manrope', Arial, sans-serif;font-size:44px;font-weight:300;color:#8A8A8F\">02</p><p style=\"font-size:32px;font-weight:500\">Firma de contrato y anticipo</p><p style=\"font-size:24px;color:#55555A;text-align:right\">{{paso_siguiente_2_fecha}}</p></div>\n<div data-build-in=\"rise 4 auto\" style=\"position:absolute;left:128px;bottom:278.6px;width:1664px;display:grid;grid-template-columns:120px 1fr 360px;gap:32px;align-items:center;padding:28px 0px;border-bottom:1px solid #E2E2DE\"><p style=\"font-family:'Manrope', Arial, sans-serif;font-size:44px;font-weight:300;color:#8A8A8F\">03</p><p style=\"font-size:32px;font-weight:500\">Sesión de arranque con tu equipo</p><p style=\"font-size:24px;color:#55555A;text-align:right\">{{paso_siguiente_3_fecha}}</p></div>\n<div data-build-in=\"rise 5 auto\" style=\"position:absolute;left:128px;bottom:160px;width:1664px;display:grid;grid-template-columns:120px 1fr 360px;gap:32px;align-items:center;padding:28px 0px;border-bottom:1px solid #E2E2DE\"><p style=\"font-family:'Manrope', Arial, sans-serif;font-size:44px;font-weight:300;color:#8A8A8F\">04</p><p style=\"font-size:32px;font-weight:500\">Primeros diseños de {{nombre_app}}</p><p style=\"font-size:24px;color:#55555A;text-align:right\">{{paso_siguiente_4_fecha}}</p></div>\n<img id=\"ark-logo\" src=\"propuesta/logo-negro.png\" alt=\"ARK\" style=\"position:absolute;left:128px;top:986px;width:43px;height:28px;object-fit:contain\">\n<div id=\"ark-footer\" style=\"position:absolute;left:128px;right:128px;bottom:64px;height:32px;display:flex;flex-direction:row;justify-content:flex-end;align-items:center\"><p style=\"font-size:24px;color:#8A8A8F\">Propuesta para {{cliente_nombre}} · 14</p></div>\n<aside>Cierra con una acción concreta: propone fecha para el paso 01 durante la llamada. Recuerda que después de la llamada se envía todo por WhatsApp. Variables: paso_siguiente_1..4_fecha (ej. \"Esta semana\", \"Lunes 12 de octubre\").</aside>\n</section>"
},
{
"id": "cierre",
"html": "<section id=\"cierre\" data-transition=\"magic\" style=\"background:#0E0E0F;color:#FAFAF8;font-family:'Inter', Arial, sans-serif;padding:128px;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:56px\">\n<img id=\"ark-logo\" src=\"propuesta/logo-portada.png\" alt=\"Logo de ARK\" style=\"position:absolute;left:838px;top:303px;width:244px;height:200px;object-fit:contain\">\n<h2 data-build-in=\"rise 1 auto\" style=\"position:absolute;left:310px;top:600px;width:1300px;transform:translateY(-50%);font-family:'Manrope', Arial, sans-serif;font-size:72px;font-weight:300;line-height:1.15;letter-spacing:-1.5px;text-align:center\">Hagamos realidad {{nombre_app}}</h2>\n<div data-build-in=\"fade 2 auto\" style=\"position:absolute;left:128px;top:698px;width:1664px;display:flex;flex-direction:row;gap:64px;justify-content:center\">\n<div style=\"display:flex;flex-direction:column;gap:6px;align-items:center\"><p style=\"font-size:24px;color:#77777C\">Tu contacto</p><p style=\"font-size:28px;font-weight:600\">{{representante_nombre}}</p></div>\n<div data-vars=\"representante_whatsapp\" style=\"display:flex;flex-direction:column;gap:6px;align-items:center\"><p style=\"font-size:24px;color:#77777C\">WhatsApp</p><p style=\"font-size:28px;font-weight:600\">{{representante_whatsapp}}</p></div>\n<div data-vars=\"representante_email\" style=\"display:flex;flex-direction:column;gap:6px;align-items:center\"><p style=\"font-size:24px;color:#77777C\">Correo</p><p style=\"font-size:28px;font-weight:600\">{{representante_email}}</p></div>\n</div>\n<aside>Agradece, pregunta si hay dudas y confirma que enviarás la propuesta y el resumen por WhatsApp hoy mismo. Variables: representante_nombre, representante_whatsapp, representante_email.</aside>\n</section>"
}
];
